arguments.command:
cd /workspace && python3 -c "
import sys; sys.path.insert(0,'/workspace/deps')
import zstandard as zstd
body=b'hello world'*10
for cs in (False,True):
  for ck in (False,True):
    d=zstd.ZstdCompressor(write_content_size=cs,write_checksum=ck).compress(body)
    p=zstd.get_frame_parameters(d)
    print('content_size',cs,'checksum',ck,'desc',bin(d[4]),'window',p.window_size,'content',p.content_size,'dict',p.dict_id,'has_ck',p.has_checksum,'hdr',zstd.frame_header_size(d))
"
